import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.CZxGLIO_.js";const k=JSON.parse('{"title":"Rooster","description":"Local process supervision, Cron scheduling, and an HTTP API for agents.","frontmatter":{"title":"Rooster","description":"Local process supervision, Cron scheduling, and an HTTP API for agents."},"headers":[],"relativePath":"en/docs/rooster/index.md","filePath":"en/docs/rooster/index.md"}'),n={name:"en/docs/rooster/index.md"};function o(r,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="rooster" tabindex="-1">Rooster <a class="header-anchor" href="#rooster" aria-label="Permalink to &quot;Rooster&quot;">​</a></h1><p>Rooster brings a local web console, native tray app, SQLite execution history, and process management together. Use it for development services, background workers, backups, and synchronization scripts.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>Install Go 1.25+, Node.js, and pnpm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/leancodebox/rooster.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rooster</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/roosterd</span></span></code></pre></div><p>Open <code>http://127.0.0.1:9090</code>. If occupied, Rooster tries the next 100 ports; use the address printed in the <code>rooster ready</code> log. The native tray entry is <code>go run ./cmd/rooster</code> and requires the platform&#39;s Fyne graphics dependencies.</p><h2 id="choose-a-task-type" tabindex="-1">Choose a task type <a class="header-anchor" href="#choose-a-task-type" aria-label="Permalink to &quot;Choose a task type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Use case</th><th>Behavior</th></tr></thead><tbody><tr><td>Resident <code>resident</code></td><td>Development services and background workers</td><td>Restart on failure, always, or never; exponential backoff</td></tr><tr><td>Scheduled <code>scheduled</code></td><td>Backups, synchronization, checks</td><td>Five-field Cron; skip overlapping runs or allow parallel execution</td></tr></tbody></table><p>Run a new task manually, inspect its history and logs, then enable automatic operation. Disabling a scheduled task stops future triggers but does not terminate an active execution. Stop that execution separately if needed. Editing and deletion require a disabled task with no active execution.</p><h2 id="data-and-environment" tabindex="-1">Data and environment <a class="header-anchor" href="#data-and-environment" aria-label="Permalink to &quot;Data and environment&quot;">​</a></h2><ul><li><code>ROOSTER_LISTEN</code>: preferred address, default <code>127.0.0.1:9090</code>.</li><li><code>ROOSTER_DATA_DIR</code>: data directory, default <code>Rooster</code> under the system user configuration directory.</li><li>The database is <code>rooster.db</code>; logs are in <code>logs/</code>. Preserve the data directory when migrating or backing up.</li><li>Configure working directories, shells, environment variables, and execution logs per task.</li></ul><h2 id="agent-access" tabindex="-1">Agent access <a class="header-anchor" href="#agent-access" aria-label="Permalink to &quot;Agent access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/health</code></td><td>Health check</td></tr><tr><td><code>GET /api/skill</code></td><td>Agent operating instructions</td></tr><tr><td><code>GET /api/docs</code></td><td>Complete API fields, responses, and examples</td></tr></tbody></table><p>The console&#39;s Agent access button copies the current instance address and documentation. An accepted execution request does not mean successful completion; inspect execution history afterward.</p><p>The service listens on loopback by default and has no remote authentication layer. Commands execute with the Rooster process user&#39;s permissions. Keep access local.</p><p><a href="https://github.com/leancodebox/rooster" target="_blank" rel="noreferrer">Source and complete guide</a> · <a href="https://github.com/leancodebox/rooster/blob/main/docs/architecture.md" target="_blank" rel="noreferrer">Architecture</a></p>`,16)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
